INSERT INTO `Tours` VALUES
(29, 'Physique - Chimie', 'Ce parcours vous permettra de découvrir l\'ensemble des laboratoires de physique et de chimie présents dans la Halle Technologique. Chaque salle est équipée de matériels pédagogiques spécifiques permettant aux étudiants de réaliser des expériences concrètes et variées.', 0),
(30, 'Rez-de-chaussée', 'Ce parcours vous permettra de découvrir l\'ensemble des salles situées au rez-de-chaussée de la Halle Technologique.', 0)
